-- BiblioHub · contenido inicial (generado desde content/seed.json, no editar a mano)
-- Ejecutar DESPUÉS de schema.sql. Es seguro volver a correrlo (upsert).

on conflict (id) do update set title=excluded.title, position=excluded.position;

on conflict (slug) do update set title=excluded.title, author=excluded.author, pages=excluded.pages, copies=excluded.copies, year=excluded.year, category_id=excluded.category_id, pdf_path=excluded.pdf_path, cover_path=excluded.cover_path, ol_rating=excluded.ol_rating, ol_votes=excluded.ol_votes, position=excluded.position;

-- equipo, sedes y efemérides: se vacían y recargan para no duplicar si se corre otra vez
truncate public.team_members, public.branches, public.events;



on conflict (key) do update set value=excluded.value, updated_at=now();
