insert into public.team_members (name,role,bio,focus,img,position) values
('Sandro','Dirección','Bibliotecólogo con más de veinte años de trayectoria en bibliotecas públicas y universitarias. Impulsa el acceso gratuito al conocimiento y la apertura de la biblioteca a todos los barrios.',array['Estrategia y alianzas','Políticas de acceso','Relación con la comunidad']::text[],2,0),
('Roxy','Colecciones y archivo','Archivista y especialista en preservación. Cuida las colecciones especiales y coordina la digitalización de fotografías, documentos y publicaciones históricas.',array['Colecciones especiales','Digitalización','Guías de investigación']::text[],3,1),
('Paula','Programas culturales','Gestora cultural y mediadora de lectura. Diseña clubes de lectura, ciclos de autores y las celebraciones del calendario literario durante todo el año.',array['Clubes de lectura','Ciclos y talleres','Primera infancia']::text[],4,2),
('Dante','Biblioteca digital','Especialista en recursos digitales y tecnología. Administra los libros electrónicos, audiolibros y cursos en línea, y enseña a los socios a sacarles el máximo provecho desde cualquier dispositivo.',array['Libros electrónicos','Cursos en línea','Alfabetización digital']::text[],1,3),
('Benjamin Cenoz','Atención y comunidad','Referencista y responsable de la atención al público. Te ayuda con tu carnet, tus préstamos y cualquier trámite, en persona o por correo.',array['Carnet y préstamos','Ayuda con la tecnología','Accesibilidad']::text[],5,4);
