insert into public.events (title,month,day,category,body) values
('Día Internacional de la Lengua Materna',1,21,'Novela y ficción','Proclamado por la UNESCO para promover la diversidad lingüística y el multilingüismo. En la biblioteca: lecturas en distintos idiomas y mesa de literatura en lenguas originarias.'),
('Día Mundial de la Poesía',2,21,'Novela y ficción','Desde 1999, la UNESCO dedica este día a la palabra poética. En la biblioteca: micrófono abierto, lecturas en voz alta y recitales para todas las edades.'),
('Día Internacional del Libro Infantil',3,2,'Infantil y juvenil','Se celebra desde 1967 en el natalicio de Hans Christian Andersen. En la biblioteca: cuentacuentos, talleres de ilustración y préstamos especiales para los más chicos.'),
('Día Mundial del Libro y del Derecho de Autor',3,23,'Novela y ficción','La UNESCO eligió esta fecha por Cervantes, Shakespeare y el Inca Garcilaso de la Vega, fallecidos en 1616. En la biblioteca: feria de intercambio de libros y charlas con autores.'),
('Día Internacional de la Alfabetización',8,8,'Historia y sociedad','Proclamado por la UNESCO para recordar que leer y escribir son derechos humanos. En la biblioteca: tutorías gratuitas y jornadas de lectura compartida.');
